function createPlanFeedback(status){let version=0;function begin(message){let request=++version;return status.hidden=!1,status.dataset.loading="true",status.textContent=message,request}function finish(request){request===version&&(status.hidden=!0,delete status.dataset.loading)}function cancel(){version++,status.hidden=!0,delete status.dataset.loading}async function run(task,message,{valid=()=>!0,ready=()=>{},error="This drawing could not load. Choose another view or reopen the floor to retry."}={}){let request=begin(message);try{return await task(),request!==version||!valid()?!1:(ready(),finish(request),!0)}catch{return request===version&&valid()&&(status.hidden=!1,status.dataset.loading="false",status.textContent=error),!1}}function image(image2,src,message,options={}){return image2.src=src,run(()=>image2.decode(),message,options)}return{begin,cancel,run,image}}export{createPlanFeedback};
